-- Limpiar changesets atascados para que Liquibase los re-ejecute
DELETE FROM DATABASECHANGELOG 
WHERE ID IN (
    '5e000000-0000-4000-8000-000000000050',
    '5e000000-0000-4000-8000-000000000051',
    '5e000000-0000-4000-8000-000000000052',
    '5e000000-0000-4000-8000-000000000053',
    '5e000000-0000-4000-8000-000000000054',
    '5e000000-0000-4000-8000-000000000055',
    '5e000000-0000-4000-8000-000000000056'
);